from enum import StrEnum
from typing import Annotated, Any, Literal, Self

from ouranos_ml.shared.domain.core.base_schema import BaseSchema
from pydantic import AliasChoices, Field, SerializerFunctionWrapHandler, model_serializer, model_validator


class ChatCompletionRole(StrEnum):
    """Represents what role an actor in a chat is."""

    USER = "user"
    ASSISTANT = "assistant"
    SYSTEM = "system"
    TOOL = "tool"


class ToolCallFunction(BaseSchema):
    """The function a tool call invokes."""

    name: str
    arguments: str
    """The arguments as a JSON string, as generated by the model (not guaranteed to be valid JSON)."""


class ToolCall(BaseSchema):
    """A function tool call made by the model."""

    id: str
    type: Literal["function"] = "function"
    function: ToolCallFunction


class RequestMessage(BaseSchema):
    """Represents a single request message in the chat.

    An assistant message may carry ``tool_calls`` instead of ``content``, and a ``tool`` message answers
    one of them by ``tool_call_id``.
    """

    role: ChatCompletionRole
    content: str | None = None
    tool_calls: list[ToolCall] | None = None
    tool_call_id: str | None = None

    @model_validator(mode="after")
    def _check_role_fields(self) -> Self:
        if self.tool_calls and self.role != ChatCompletionRole.ASSISTANT:
            raise ValueError("Only assistant messages can have 'tool_calls'")
        if (self.tool_call_id is not None) != (self.role == ChatCompletionRole.TOOL):
            raise ValueError("'tool_call_id' is required on tool messages and not allowed on others")
        if self.content is None and not self.tool_calls:
            raise ValueError("'content' is required unless the message has 'tool_calls'")
        return self


class FunctionDefinition(BaseSchema):
    """A function the model may call."""

    name: str
    description: str | None = None
    parameters: dict[str, Any] | None = None
    """The function's parameters, described as a JSON Schema object."""
    strict: bool | None = None


class FunctionTool(BaseSchema):
    """A function tool (the only tool type chat supports)."""

    type: Literal["function"] = "function"
    function: FunctionDefinition


class NamedFunction(BaseSchema):
    """The function a named tool choice forces."""

    name: str


class NamedToolChoice(BaseSchema):
    """Forces the model to call a specific function."""

    type: Literal["function"] = "function"
    function: NamedFunction


ToolChoiceMode = Literal["none", "auto", "required"]


class StreamOptions(BaseSchema):
    """Options for streaming response. Only set when stream is true."""

    include_usage: bool = False
    """If set, an additional chunk will be streamed before the [DONE] message
    with total token usage. All other chunks will include a null usage field."""


class JSONSchemaConfig(BaseSchema):
    """Structured Outputs configuration, including the JSON Schema to conform to."""

    name: str
    """The name of the response format. Must be a-z, A-Z, 0-9, or contain
    underscores and dashes, with a maximum length of 64."""

    description: str | None = None
    """A description of what the response format is for, used by the model to
    determine how to respond in the format."""

    strict: bool | None = None
    """Whether to enable strict schema adherence when generating the output.
    If set to true, the model will always follow the exact schema defined in
    the schema field."""

    json_schema: dict[str, Any] | None = Field(default=None, alias="schema")
    """The schema for the response format, described as a JSON Schema object.

    Uses the OpenAI wire name ``schema``; the Python field name avoids shadowing
    the deprecated ``BaseModel.schema`` classmethod.
    """


class ResponseFormatText(BaseSchema):
    """Default response format used to generate text responses."""

    type: Literal["text"] = "text"


class ResponseFormatJSONObject(BaseSchema):
    """JSON object response format, forcing the model to output valid JSON."""

    type: Literal["json_object"]


class ResponseFormatJSONSchema(BaseSchema):
    """JSON Schema response format used to generate structured JSON responses."""

    type: Literal["json_schema"]
    json_schema: JSONSchemaConfig = Field(
        alias="json_schema", validation_alias=AliasChoices("jsonSchema", "json_schema")
    )


ResponseFormat = Annotated[
    ResponseFormatText | ResponseFormatJSONObject | ResponseFormatJSONSchema,
    Field(discriminator="type"),
]


class ChatCompletionsRequest(BaseSchema):
    """Request for generating a chat completion."""

    model: str
    messages: list[RequestMessage] = Field(min_length=1)

    top_p: float | None = None
    temperature: float | None = None
    max_completion_tokens: int | None = None
    stream: bool | None = False
    stream_options: StreamOptions | None = None
    response_format: ResponseFormat | None = None
    stop: str | list[str] | None = None
    presence_penalty: float | None = None
    frequency_penalty: float | None = None
    logit_bias: dict[str, int] | None = None
    tools: list[FunctionTool] | None = None
    tool_choice: ToolChoiceMode | NamedToolChoice | None = None
    parallel_tool_calls: bool | None = None


class ChoiceMessage(BaseSchema):
    """Message in a chat completion response."""

    role: ChatCompletionRole
    content: str | None
    """The message text; ``None`` when the model only called tools."""
    reasoning_content: str | None = None
    """The model's reasoning, as llama.cpp sends it for thinking models."""
    tool_calls: list[ToolCall] | None = None
    refusal: str | None = None


class Choice(BaseSchema):
    """Choice from the chat completion."""

    finish_reason: str
    index: int
    message: ChoiceMessage


class Usage(BaseSchema):
    """Usage statistics for the chat completion"""

    prompt_tokens: int = 0
    completion_tokens: int = 0
    total_tokens: int = 0


class ChatCompletionsResponse(BaseSchema):
    """Response for chat completions."""

    id: str
    object: str = "chat.completion"
    created: int
    model: str
    choices: list[Choice]
    usage: Usage
    system_fingerprint: str | None


class _ToolCallPiece(BaseSchema):
    """Omits unset fields when serialized, as upstream does on continuation pieces.

    Clients merge pieces field by field, so an explicit ``null`` would overwrite the ``id``, ``type`` or
    ``name`` sent by the first piece (the OpenAI SDK's stream accumulator fails on it).
    """

    @model_serializer(mode="wrap")
    def _omit_none(self, handler: SerializerFunctionWrapHandler) -> dict[str, Any]:
        return {key: value for key, value in handler(self).items() if value is not None}


class ChunkToolCallFunction(_ToolCallPiece):
    """A piece of a streamed tool call's function; ``arguments`` arrives in fragments to concatenate."""

    name: str | None = None
    arguments: str | None = None


class ChunkToolCall(_ToolCallPiece):
    """A piece of a streamed tool call; pieces with the same ``index`` belong to one call."""

    index: int
    id: str | None = None
    type: Literal["function"] | None = None
    function: ChunkToolCallFunction | None = None


class ChunkDelta(BaseSchema):
    """Delta for a chunk."""

    content: str | None
    reasoning_content: str | None = None
    """A piece of the model's reasoning, as llama.cpp sends it for thinking models."""
    tool_calls: list[ChunkToolCall] | None = None


class ChunkChoice(BaseSchema):
    """Choice from a streamed chat."""

    index: int
    delta: ChunkDelta
    finish_reason: Literal["stop", "length", "tool_calls", "content_filter", "function_call"] | None


class ChatCompletionChunkResponse(BaseSchema):
    """Response for a streamed chat completion."""

    id: str
    object: str = "chat.completion.chunk"
    created: int
    model: str
    system_fingerprint: str | None
    choices: list[ChunkChoice]
    usage: Usage | None = None
